import numpy as np

rng = np.random.RandomState(42)
vocabulary = ["a", "dog", "cat", "runs", "sits", "on", "the", "grass", "END"]

def choose_next_word(previous_words, image_features, rng):
    # a genuinely simplified stand-in for a real decoder, already covered as sequential word generation in this topic
    if len(previous_words) == 0:
        return "a"
    elif previous_words[-1] == "a":
        return rng.choice(["dog", "cat"])
    elif previous_words[-1] in ("dog", "cat"):
        return rng.choice(["runs", "sits"])
    elif previous_words[-1] in ("runs", "sits"):
        return "on"
    elif previous_words[-1] == "on":
        return "the"
    elif previous_words[-1] == "the":
        return "grass"
    else:
        return "END"

image_features = rng.normal(size=10)  # already covered as the encoder's own output in this topic
caption_words = []

while True:
    next_word = choose_next_word(caption_words, image_features, rng)
    if next_word == "END":
        break
    caption_words.append(next_word)

print("Generated caption:", " ".join(caption_words))
print("\nEach word was generated one at a time, conditioned on prior words, already covered as sequential word generation in this topic")
